import{_ as o,C as n,o as r,c as d,a7 as a,j as s,a as t,E as l}from"./chunks/framework.C4ZIv4ii.js";const y=JSON.parse('{"title":"Backups & Moving a Site","description":"","frontmatter":{},"headers":[],"relativePath":"guide/backups.md","filePath":"guide/backups.md","lastUpdated":1793807644000}'),h={name:"guide/backups.md"},p={id:"moving",tabindex:"-1"};function c(k,e,u,g,m,b){const i=n("Badge");return r(),d("div",null,[e[3]||(e[3]=a('<h1 id="backups-moving-a-site" tabindex="-1">Backups &amp; Moving a Site <a class="header-anchor" href="#backups-moving-a-site" aria-label="Permalink to &quot;Backups &amp; Moving a Site&quot;">​</a></h1><p><strong>Tools → Backup</strong> makes a copy of your site in one file, and puts a site back from one — the same site after a mistake, or a whole site on another server or address.</p><h2 id="making-a-backup" tabindex="-1">Making a backup <a class="header-anchor" href="#making-a-backup" aria-label="Permalink to &quot;Making a backup&quot;">​</a></h2><p>Choose what to include:</p><ul><li><strong>Database</strong> — posts, pages, users, menus, settings and everything else stored in the database (a <code>.sql</code> file).</li><li><strong>Media</strong> — uploaded images and files (a <code>.zip</code>).</li><li><strong>Database + Media</strong> — both in one <code>.zip</code>: a complete copy of the site.</li></ul><p>Download the file and keep it somewhere safe, off the server.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Database backups need MySQL or MariaDB. On SQLite, media backups still work.</p></div><h2 id="restoring" tabindex="-1">Restoring <a class="header-anchor" href="#restoring" aria-label="Permalink to &quot;Restoring&quot;">​</a></h2><p>Click <strong>Restore</strong> beside a backup in the list. A backup made on another site is first uploaded with <strong>Upload Backup from Another Site</strong>, then restored the same way.</p><p>Restore works out by itself what a file holds — a database, media, or both — and brings it back. A full restore can take a while; it carries on on the server even if the browser gives up waiting.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Restoring the database replaces the site&#39;s current content and users with the backup&#39;s. Make a backup of the current site first if you might want it back.</p></div>',11)),s("h2",p,[e[0]||(e[0]=t("Moving a site to another address ",-1)),l(i,{type:"tip",text:"2.9.0"}),e[1]||(e[1]=t()),e[2]||(e[2]=s("a",{class:"header-anchor",href:"#moving","aria-label":'Permalink to "Moving a site to another address <Badge type="tip" text="2.9.0" /> {#moving}"'},"​",-1))]),e[4]||(e[4]=a(`<p>Moving the live site to a local copy, a staging server or a new domain is a backup on one and a restore on the other. <strong>Links to the old address are changed to the new one by themselves</strong> — you don&#39;t search and replace anything.</p><p>A backup records the address of the site it was made on. When it is restored on a different address, every link to the old address becomes a link to this one:</p><ul><li>menus, buttons and links in builder layouts and post content</li><li>settings (logo, social links and so on) and page revisions</li><li>links written inside JSON, inside PHP-serialized values, and URL-encoded inside other links (share buttons, embeds)</li><li><code>http</code> and <code>https</code>, with or without <code>www</code></li></ul><p>The message after the restore says how many links moved, and from where to where. The site&#39;s caches are cleared, so the new links show at once.</p><p><strong>Left as they were:</strong></p><ul><li>other domains — <code>demo.example.com</code> or <code>example.com.au</code> when the old site was <code>example.com</code></li><li>e-mail addresses, and a domain written as plain text without <code>http</code></li><li>visit logs, the 404 log, Search Console figures and similar records of what happened on the old site</li></ul><p>A backup made before 2.9.0 does not record its address; the old address is then read from the data (where its menu items and media point).</p><h3 id="menus-under-any-address" tabindex="-1">Menus under any address <a class="header-anchor" href="#menus-under-any-address" aria-label="Permalink to &quot;Menus under any address&quot;">​</a></h3><p>Menu items for pages, posts and categories are worked out from the item when the page is shown, and links to the site itself are written as paths (<code>/about</code>). So menus are right whatever address the site is opened at — even a copy reached both as <code>mysite.test</code> and as <code>127.0.0.1:8000</code>.</p><h2 id="replace-url" tabindex="-1">Changing addresses by hand <a class="header-anchor" href="#replace-url" aria-label="Permalink to &quot;Changing addresses by hand {#replace-url}&quot;">​</a></h2><p>Data copied in some other way — imported straight into the database, say — can be moved with the <code>falcon:replace-url</code> command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Links to the old site → this site&#39;s APP_URL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> falcon:replace-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://old-site.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># … or to an address you give</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> falcon:replace-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://old-site.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://new-site.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Drop the address and keep the path (/about): right under any address</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> falcon:replace-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://old-site.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relative</span></span></code></pre></div><p>With no old address, the command works it out from the data and asks before changing anything (<code>--force</code> skips the question). It lists how many values changed in each table.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Set <code>APP_URL</code> in <code>.env</code> to the address the site is actually opened at, then run <code>php artisan config:clear</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A builder tab left open from before a move still holds the old links. Saving it brings them back. Close such tabs without saving and open the page again.</p></div>`,15))])}const v=o(h,[["render",c]]);export{y as __pageData,v as default};
